/* ==========================================================
   works-sec  (Webflow: .works-sec)
   ========================================================== */
.worksSec {
  background-color: transparent;
  padding: 20px 5% 60px;
  position: relative;
}

/* ==========================================================
   Container  (Webflow: .container-large-3)
   ========================================================== */
.containerLarge3 {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* ==========================================================
   Badge row  (Webflow: .benefit-subhead-out / .benefitsubott)
   ========================================================== */
.benefitSubheadOut {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  justify-content: center;
  align-items: center;
  display: flex;
}

.benefitsubott {
  background-color: #21cfff12;
  border: 1px solid #05bafe;
  border-radius: 20px;
  margin-bottom: 0;
  padding: 0 13px;
  line-height: 14px;
}

/* ==========================================================
   Gradient text  (Webflow: .faq-sky-text)
   ========================================================== */
.faqSkyText {
  color: #21cfff;
  text-transform: capitalize;
  -webkit-text-fill-color: transparent;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
  font-weight: 500;
}

/* ==========================================================
   Section heading  (Webflow: .heading-2.margin-bottom-24px)
   ========================================================== */
.heading2 {
  color: #082753;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 40px;
  text-align: center;
  line-height: 45px;
  margin-bottom: 20px;
}

/* ==========================================================
   Body copy  (Webflow: .paragraph.center)
   ========================================================== */
.paragraph {
  color: #2b2b2b;
  font-size: 16px;
  line-height: 28px;
  text-align: center;
  margin-bottom: 0;
}

/* ==========================================================
   Grid  (Webflow: .feature-grid.margin-top-40px.hiring-slider)
   Desktop: 3-col grid with scroll snapping disabled — Slick
   converts it to carousel only at < 980px in Webflow. We
   replicate with CSS scroll-snap at ≤767px.
   ========================================================== */
.featureGrid {
  display: grid;
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr;
  margin-top: 40px;
}

/* ==========================================================
   Card  (Webflow: .feature-card.space-between)
   Note: .space-between modifier sets justify-content: space-between
   ========================================================== */
.featureCard {
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  text-align: center;
  mix-blend-mode: normal;
  background-color: #def4ff;
  background-image: none;
  border: 1px solid #009ce0;
  border-radius: 20px;
  flex-flow: column;
  justify-content: space-between;
  align-items: center;
  padding: 25px 17px 17px;
  text-decoration: none;
  display: flex;
}

.featureCard:hover {
  background-color: #cdebfa;
  border-color: #009ce0;
}

/* ==========================================================
   Text wrapper  (Webflow: .text-wrapper)
   ========================================================== */
.textWrapper {
  margin-bottom: 20px;
}

/* ==========================================================
   Card title  (Webflow: .subheading-large)
   ========================================================== */
.subheadingLarge {
  color: #082753;
  letter-spacing: -0.02em;
  margin-bottom: 10px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 25px;
}

/* ==========================================================
   Card body copy  (Webflow: .paragraph-small-2.margin-bottom-20px.grid-wrap)
   ========================================================== */
.paragraphSmall2 {
  color: #2b2b2b;
  min-height: auto;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 16px;
  letter-spacing: -0.08px;
  margin-bottom: 0;
  line-height: 28px;
  max-width: 315px;
}

/* ==========================================================
   Card image  (Webflow: .full-width-image.drop-shadow.blue-shadow)
   ========================================================== */
.fullWidthImage {
  display: block;
  width: 100%;
  height: auto;
  filter: drop-shadow(0px 0px 30px rgba(0, 126, 188, 0.1));
}

/* ==========================================================
   Dots (CSS scroll indicator — replaces Slick dots at mobile)
   ========================================================== */
.sliderDots {
  display: none;
}

/* ==========================================================
   @media (min-width: 1280px)
   Webflow line 21922 — .feature-card, .container-large-3
   ========================================================== */
@media screen and (min-width: 1280px) {
  .featureCard {
    background-color: #def4ff;
    border-color: #009ce0;
  }

  .containerLarge3 {
    max-width: 1280px;
  }

  .paragraphSmall2 {
    max-width: 308px;
  }
}

/* ==========================================================
   @media (min-width: 1440px)
   Webflow line 23357 — .feature-card.space-between gets pl/pr 25px
   container-large-3 gets max-width: 1320px
   ========================================================== */
@media screen and (min-width: 1440px) {
  .featureCard {
    background-color: #def4ff;
    background-image: none;
    border-color: #009ce0;
    justify-content: space-between;
    align-items: center;
    padding-left: 25px;
    padding-right: 25px;
  }

  .containerLarge3 {
    max-width: 1320px;
  }

  .paragraphSmall2 {
    max-width: 308px;
    margin-left: auto;
    margin-right: auto;
  }
}

/* ==========================================================
   @media (max-width: 991px)
   Webflow line 24558: feature-grid → 1 col (but margin-top-40px → 3 col)
   So .hiring-slider (which also has margin-top-40px) stays 3-col at tablet
   ========================================================== */
@media screen and (max-width: 991px) {
  .featureGrid {
    /* hiring-slider keeps 3-col at tablet per Webflow line 24562 */
    grid-template-columns: 1fr 1fr 1fr;
    grid-column-gap: 20px;
    grid-row-gap: 20px;
  }

  .paragraphSmall2 {
    max-width: none;
  }

  .heading2 {
    font-size: 35px;
    line-height: 45px;
  }
}

/* ==========================================================
   @media (max-width: 767px)
   Webflow line 27051: .feature-grid.margin-top-40px → 1 col
   Webflow line 27055: .feature-grid.margin-top-40px.hiring-slider → 20px gap (Slick takes over)
   Webflow line 27177: .works-sec → padding-top: 0; padding-bottom: 50px
   We implement hiring-slider as CSS horizontal scroll carousel
   ========================================================== */
@media screen and (max-width: 767px) {
