  }

  /* Horizontal scroll carousel mimicking Slick slidesToShow:2 at tablet */
  .featureGrid {
    grid-template-columns: unset;
    grid-template-rows: unset;
    display: flex;
    flex-direction: row;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    -webkit-overflow-scrolling: touch;
    scroll-padding-left: 5%;
    gap: 20px;
    margin-top: 20px;
    /* hide scrollbar */
    scrollbar-width: none;
  }

  .featureGrid::-webkit-scrollbar {
    display: none;
  }

  .featureCard {
    flex: 0 0 calc(50% - 10px);
    min-width: calc(50% - 10px);
    scroll-snap-align: start;
    grid-column-gap: 0px;
    grid-row-gap: 0px;
    padding-left: 18px;
    padding-right: 18px;
  }

  .paragraphSmall2 {
